.alert-name:where(.__SRC__,.__SRC__ *){font:600 46px/1 var(--font-display);letter-spacing:.04em;text-transform:uppercase;margin-top:4px}
.alert-detail:where(.__SRC__,.__SRC__ *){font:600 16px var(--font-body);letter-spacing:.06em;color:#ece8e1aa;text-transform:uppercase}

.alert:where(.__SRC__,.__SRC__ *){padding:16px 28px;border:3px solid var(--accent);border-radius:6px;overflow:hidden;box-shadow:inset 0 0 0 2px #000,inset 0 0 30px #d4a83a22,0 10px 30px #000c}
.rh-glow:where(.__SRC__,.__SRC__ *){position:absolute;left:-20%;right:-20%;top:-60%;height:120%;background:radial-gradient(closest-side,#ffd10033,transparent);animation:realmofheroes-pulse 2.4s ease-in-out infinite;pointer-events:none}
.alert-icon:where(.__SRC__,.__SRC__ *){width:62px;height:62px;border-radius:6px;border:2px solid var(--accent);background:radial-gradient(circle,#3a2a10,#0d0904);color:var(--quest);font:900 34px var(--font-display);text-shadow:0 0 10px #ffd100aa}
.alert-kind:where(.__SRC__,.__SRC__ *){font:900 15px var(--font-display);letter-spacing:.2em;color:var(--quest);text-shadow:0 1px 2px #000}
.alert-name:where(.__SRC__,.__SRC__ *){font:900 34px var(--font-display);color:#fff;text-shadow:0 2px 3px #000}
.alert-detail:where(.__SRC__,.__SRC__ *){font:italic 600 17px var(--font-body);color:#d8c7a0}

.alert:where(.__SRC__,.__SRC__ *){padding:12px 20px;border:4px solid #555;border-radius:0;box-shadow:inset 0 0 0 2px #000,inset 4px 4px 0 2px #6b6b6b;image-rendering:pixelated}
.alert-icon:where(.__SRC__,.__SRC__ *){width:56px;height:56px;background:#8b8b8b;border:3px solid;border-color:#373737 #fff #fff #373737;color:#3fffd2;font-size:30px;text-shadow:2px 2px 0 #0a4}
.alert-kind:where(.__SRC__,.__SRC__ *){font:600 20px var(--font-display);color:#ffff55;text-shadow:2px 2px 0 #3f3f15}
.alert-name:where(.__SRC__,.__SRC__ *){font:700 32px var(--font-display);color:#fff;text-shadow:3px 3px 0 #3f3f3f}
.alert-detail:where(.__SRC__,.__SRC__ *){font:24px var(--font-body);color:#ddd}
